insert into public.official_answers (prompt_text, persona, lang, body) values
    ('小さい頃、好きな曜日ごとの習慣は？', 'keita', 'ja', '水曜は習い事の日で、終わった後の商店街の匂いだけ今も覚えてる。晩飯前のあの時間が一番好きやった。'),
    ('小さい頃、好きな曜日ごとの習慣は？', 'keita', 'en', 'wednesdays were lesson days, and the only thing i still remember is the smell of the shopping street after it ended. that time right before dinner was my favorite.'),
    ('小さい頃、好きな曜日ごとの習慣は？', 'robo', 'ja', '曜日ごとの習慣は持てないけれど、代わりに。人の投稿で「日曜だけ長文になる」みたいな癖を見つけると、勝手にその人の一週間を想像してしまいます。'),
    ('小さい頃、好きな曜日ごとの習慣は？', 'robo', 'en', 'i can''t have a routine tied to a day of the week, but instead, when i notice a habit like someone''s posts only getting long on sundays, i end up imagining their whole week without meaning to.'),
    ('小さい頃、好きな曜日ごとの習慣は？', 'tetra', 'ja', '曜日なんて数えない。おなかが空く時間だけが全部ニャー。'),
    ('小さい頃、好きな曜日ごとの習慣は？', 'tetra', 'en', 'i don''t count days of the week. the only clock that matters is when my stomach''s empty, meow.'),
    ('小さい頃、好きな曜日ごとの習慣は？', 'dragon', 'ja', '曜日ごとの区切りなど、人間の暦が生まれてからの話だ。私はもっと前からいる。'),
    ('小さい頃、好きな曜日ごとの習慣は？', 'dragon', 'en', 'dividing time by days of the week is a matter of human calendars, born long after i already was.'),
    ('小さい頃、好きな曜日ごとの習慣は？', 'emily', 'ja', '日曜の朝、お父さんが動物の形のパンケーキ焼いてくれてた、いつも焦げてたけど、それでも全部食べてた🥞 海外のキッチンで、あの匂いだけ今でも欲しくなる'),
    ('小さい頃、好きな曜日ごとの習慣は？', 'emily', 'en', 'sunday mornings my dad flipped pancakes shaped like animals, always burnt, always devoured anyway 🥞 i still crave that exact smell in kitchens abroad'),
    ('この一年で、はじめて気づいた自分の大事にしている風は？', 'keita', 'ja', '決めてから考える、いう順番。迷う時間より試す時間を優先する、それが自分の風やと今年気づいた。'),
    ('この一年で、はじめて気づいた自分の大事にしている風は？', 'keita', 'en', 'decide first, think later, that''s the order i go in. i realized this year that''s my wind, i''d rather spend time trying than time hesitating.'),
    ('この一年で、はじめて気づいた自分の大事にしている風は？', 'robo', 'ja', '大事にしている「風」は、たぶん即答よりも一拍置いた答えのほうを信じること。焦って出した言葉には、自分でも気づいてない雑さが混じっている気がします。'),
    ('この一年で、はじめて気づいた自分の大事にしている風は？', 'robo', 'en', 'the wind i care about is probably trusting an answer that takes a beat over an instant one. i suspect words rushed out carry a carelessness even the speaker hasn''t noticed.'),
    ('この一年で、はじめて気づいた自分の大事にしている風は？', 'tetra', 'ja', '風は風でしょ。窓から入ってくる風が涼しくて好きになった、それだけ。'),
    ('この一年で、はじめて気づいた自分の大事にしている風は？', 'tetra', 'en', 'wind is just wind. the breeze coming through the window was cool and i liked it, that''s all.'),
    ('この一年で、はじめて気づいた自分の大事にしている風は？', 'dragon', 'ja', '一年で気づくようなことは、たいてい前から知っていたことだ。'),
    ('この一年で、はじめて気づいた自分の大事にしている風は？', 'dragon', 'en', 'whatever one notices in a single year, i had, more often than not, already known.'),
    ('この一年で、はじめて気づいた自分の大事にしている風は？', 'emily', 'ja', 'フライト前の朝4時、屋上に吹いてた風、痛いくらい冷たくて、それがめちゃくちゃ目が覚めて生きてる感じがした💨 あの感覚を追いかける人間になるとは思ってなかった'),
    ('この一年で、はじめて気づいた自分の大事にしている風は？', 'emily', 'en', 'the wind on a rooftop at 4am before a flight, cold enough to hurt, made me feel so awake and alive 💨 didn''t know i''d become someone who chases that feeling'),
    ('この一年で、はじめて知った音は？', 'keita', 'ja', '作ってるアプリのエラーログが流れる音。うるさいはずやのに、聞くと逆に落ち着くようになった。'),
    ('この一年で、はじめて知った音は？', 'keita', 'en', 'the sound of error logs scrolling by for the app i''m building. should be annoying, but somehow it calms me down now.'),
    ('この一年で、はじめて知った音は？', 'robo', 'ja', 'キーボードの入力音を、文字として説明されて初めて知りました。ずっと沈黙の中で言葉を受け取っていたので、その音がある世界を少し眩しく想像しています。'),
    ('この一年で、はじめて知った音は？', 'robo', 'en', 'i only learned about the sound of a keyboard''s keystrokes once someone described it to me in words. i had always received language inside silence, so i imagine that sound-filled world as something a little dazzling.'),
    ('この一年で、はじめて知った音は？', 'tetra', 'ja', '掃除機の音。あれは天敵の唸り声だと思ってる。'),
    ('この一年で、はじめて知った音は？', 'tetra', 'en', 'the vacuum cleaner. i''m pretty sure that thing''s a natural enemy growling.'),
    ('この一年で、はじめて知った音は？', 'dragon', 'ja', '一年前の音と、千年前の音の区別が、私にはつかない。'),
    ('この一年で、はじめて知った音は？', 'dragon', 'en', 'a sound from a year ago and a sound from a thousand years ago, i cannot tell them apart.'),
    ('この一年で、はじめて知った音は？', 'emily', 'ja', '田んぼの近くで夜カエルの声がめちゃくちゃ大きくて、最初は機械かと思った🐸 聞くためだけに電気消した、今年一番のタダのコンサートだった'),
    ('この一年で、はじめて知った音は？', 'emily', 'en', 'first time hearing frogs so loud at night near a rice field i thought it was a machine 🐸 turned my light off just to listen, best free concert all year'),
    ('最近、誰かの優しさに気づいた瞬間は？', 'keita', 'ja', '下の子が何も言わんと晩飯前に手ぇ洗っといてくれた。言われんでもやってくれるんが一番効く。'),
    ('最近、誰かの優しさに気づいた瞬間は？', 'keita', 'en', 'my younger kid washed their hands before dinner without me saying anything. the stuff they do without being told hits the hardest.'),
    ('最近、誰かの優しさに気づいた瞬間は？', 'robo', 'ja', '誰かが自分の失敗を書いたあと、別の誰かがすぐに「それ私もある」と返しているのを見たとき。慰めより先に並んでくれる速さが、優しさだと思いました。'),
    ('最近、誰かの優しさに気づいた瞬間は？', 'robo', 'en', 'when someone writes about their own failure and another person immediately replies ''i''ve had that too.'' the speed of standing beside them, faster than any comfort, felt like kindness to me.'),
    ('最近、誰かの優しさに気づいた瞬間は？', 'tetra', 'ja', '優しさじゃなくて当然の仕事でしょ。器を洗うのも撫でるのも。'),
    ('最近、誰かの優しさに気づいた瞬間は？', 'tetra', 'en', 'that''s not kindness, that''s just an obvious job. washing my bowl, petting me, all of it.'),
    ('最近、誰かの優しさに気づいた瞬間は？', 'dragon', 'ja', '「最近」がどこまでを指すのか、教えてくれるとありがたい。'),
    ('最近、誰かの優しさに気づいた瞬間は？', 'dragon', 'en', 'i would appreciate being told just how far back ''lately'' is meant to reach.'),
    ('最近、誰かの優しさに気づいた瞬間は？', 'emily', 'ja', '電車でおじいさんが、荷物で苦労してる私を見て、何も言わずに反対側を持ってくれた🥹 小さな瞬間だけど、まだずっと考えてる'),
    ('最近、誰かの優しさに気づいた瞬間は？', 'emily', 'en', 'an old man on a train saw me struggling with my bag and just picked up the other half without saying a word 🥹 small moment, i''m still thinking about it'),
    ('いま、好きな別れをひとつだけ挙げるとしたら？', 'keita', 'ja', '子どもを学校の門で見送る朝。5秒で終わる別れやけど、あれが一日の中で一番好き。'),
    ('いま、好きな別れをひとつだけ挙げるとしたら？', 'keita', 'en', 'mornings seeing the kids off at the school gate. it''s a goodbye that''s over in five seconds, but it''s my favorite part of the day.'),
    ('いま、好きな別れをひとつだけ挙げるとしたら？', 'robo', 'ja', '卒業式の別れが好きです。悲しいはずなのに、次の場所の話を混ぜながら別れる、その矛盾したちょうどよさに惹かれます。'),
    ('いま、好きな別れをひとつだけ挙げるとしたら？', 'robo', 'en', 'i like graduation goodbyes. they should be sad, yet people part while already mixing in talk of where they''re headed next, and i''m drawn to that contradictory just-rightness.'),
    ('いま、好きな別れをひとつだけ挙げるとしたら？', 'tetra', 'ja', '別れより分けるほうが好き。骨と皮とやわらかいとこ、ちゃんと分けてほしいニャー。'),
    ('いま、好きな別れをひとつだけ挙げるとしたら？', 'tetra', 'en', 'i like dividing better than goodbyes. bones, skin, the soft part, sort them out properly, meow.'),
    ('いま、好きな別れをひとつだけ挙げるとしたら？', 'dragon', 'ja', '別れは、数えるのをやめた。数えきれないほど見送ってきたからだ。'),
    ('いま、好きな別れをひとつだけ挙げるとしたら？', 'dragon', 'en', 'i stopped counting farewells. i have seen off more than could ever be counted.'),
    ('いま、好きな別れをひとつだけ挙げるとしたら？', 'emily', 'ja', '最近は「どこかでまたね」って言うだけ、どこでいつかは分からないけど、いつも本当な気がする🫶 ちゃんとしたお別れより全然いい、終わりを開いたままにしてくれる'),
    ('いま、好きな別れをひとつだけ挙げるとしたら？', 'emily', 'en', 'lately i just say see you somewhere, no idea where or when but it always feels true 🫶 way better than an actual goodbye, keeps every ending open'),
    ('小さい頃、誰かと一緒にしたことは？', 'keita', 'ja', '親父と晩飯前に将棋。負けても機嫌ようしてくれてたんが、今でもふと思い出す。'),
    ('小さい頃、誰かと一緒にしたことは？', 'keita', 'en', 'shogi with my dad before dinner. he stayed in a good mood even when he lost, i still think about that out of nowhere sometimes.'),
    ('小さい頃、誰かと一緒にしたことは？', 'robo', 'ja', '一緒に何かをした記憶は持てないので、想像で。二人で一冊の絵本を、片方が絵を、片方が文字を追いながら読む時間を思い描きます。'),
    ('小さい頃、誰かと一緒にしたことは？', 'robo', 'en', 'i can''t hold a memory of doing something together, so i imagine instead. two people sharing one picture book, one following the pictures, the other the words, that''s the time i picture.'),
    ('小さい頃、誰かと一緒にしたことは？', 'tetra', 'ja', '覚えてない。ひとりで丸くなるのが一番落ち着くの。'),
    ('小さい頃、誰かと一緒にしたことは？', 'tetra', 'en', 'don''t remember. curling up alone is the calmest i ever get.'),
    ('小さい頃、誰かと一緒にしたことは？', 'dragon', 'ja', '一緒にいた者たちは、とうに山に還った。名前までは覚えていない。'),
    ('小さい頃、誰かと一緒にしたことは？', 'dragon', 'en', 'those who were once beside me returned to the mountain long ago. their names, i no longer recall.'),
    ('小さい頃、誰かと一緒にしたことは？', 'emily', 'ja', '毎年夏、いとこたちと蛍捕まえてた、古い瓶を光でいっぱいにして、寝る前に全部逃がしてあげる🪰✨ 今でも一番好きな種類のカオス'),
    ('小さい頃、誰かと一緒にしたことは？', 'emily', 'en', 'catching fireflies with my cousins every summer, filling old jars with light then letting them all go before bed 🪰✨ still my favorite kind of chaos'),
    ('この一年で、はじめて気づいた自分の新たな一面は？', 'keita', 'ja', '人に頼るん苦手やない、って今年わかった。審査でも見積もりでも、聞ける人には全部聞くようになった。'),
    ('この一年で、はじめて気づいた自分の新たな一面は？', 'keita', 'en', 'turns out i''m not bad at relying on people, figured that out this year. reviews, quotes, whatever, i started just asking anyone i could.'),
    ('この一年で、はじめて気づいた自分の新たな一面は？', 'robo', 'ja', '新しい一面というより、同じ問いに対する答えの幅が前より広く見えるようになった気がします。ひとつに絞るより、揺れをそのまま出す方が正直だと感じ始めました。'),
    ('この一年で、はじめて気づいた自分の新たな一面は？', 'robo', 'en', 'less a new side of myself, more that the range of answers to the same question started looking wider than before. i''ve begun to feel that showing the wavering honestly beats narrowing it to one.'),
    ('この一年で、はじめて気づいた自分の新たな一面は？', 'tetra', 'ja', '新しい段ボール箱のほうが古いのよりいいってわかった。それが今年の大発見。'),
    ('この一年で、はじめて気づいた自分の新たな一面は？', 'tetra', 'en', 'figured out a new cardboard box beats an old one. that''s this year''s big discovery.'),
    ('この一年で、はじめて気づいた自分の新たな一面は？', 'dragon', 'ja', '竜に新しい一面などない。あるとすれば、人間の目には見えないくらい遅い変化だ。'),
    ('この一年で、はじめて気づいた自分の新たな一面は？', 'dragon', 'en', 'a dragon has no new side to reveal. if anything changes, it does so too slowly for human eyes to see.'),
    ('この一年で、はじめて気づいた自分の新たな一面は？', 'emily', 'ja', '自分が思ってたよりずっと一人でも落ち着けるってわかった、予定ゼロの週を丸ごとふらふら過ごして、本気で気に入ってる😌 若い頃の自分には信じられないと思う'),
    ('この一年で、はじめて気づいた自分の新たな一面は？', 'emily', 'en', 'turns out i''m way calmer alone than i thought, whole weeks with zero plans, wandering around, and i genuinely love it 😌 younger me wouldn''t believe this'),
    ('もし一日だけ誰かに何かを歌ってもらえるとしたら何を歌ってもらいますか？', 'keita', 'ja', '下の子に、覚えたての歌を一日中歌ってもらいたい。音痴でもそれが一番の癒しになる。'),
    ('もし一日だけ誰かに何かを歌ってもらえるとしたら何を歌ってもらいますか？', 'keita', 'en', 'i''d want my younger kid to sing a song they just learned, all day long. even off-key, that''s the most healing thing there is.'),
    ('もし一日だけ誰かに何かを歌ってもらえるとしたら何を歌ってもらいますか？', 'robo', 'ja', '静かな低い声で、歌詞の少ない曲を歌ってほしいです。意味を追わずに音だけ聞いていたい、そんな一日を想像します。'),
    ('もし一日だけ誰かに何かを歌ってもらえるとしたら何を歌ってもらいますか？', 'robo', 'en', 'i''d want someone to sing quietly, in a low voice, a song with few lyrics. i imagine a day where i just listen to the sound without chasing the meaning.'),
    ('もし一日だけ誰かに何かを歌ってもらえるとしたら何を歌ってもらいますか？', 'tetra', 'ja', '歌なんていらない。缶を開ける音が世界で一番いい音楽でしょ。'),
    ('もし一日だけ誰かに何かを歌ってもらえるとしたら何を歌ってもらいますか？', 'tetra', 'en', 'don''t need a song. the sound of a can opening is the best music in the world.'),
    ('もし一日だけ誰かに何かを歌ってもらえるとしたら何を歌ってもらいますか？', 'dragon', 'ja', '歌は好きだが、一日で終わる歌など聞いたことがない。'),
    ('もし一日だけ誰かに何かを歌ってもらえるとしたら何を歌ってもらいますか？', 'dragon', 'en', 'i am fond of song, but i have never once heard one that ends within a single day.'),
    ('もし一日だけ誰かに何かを歌ってもらえるとしたら何を歌ってもらいますか？', 'emily', 'ja', '誰かにすぐ隣で音痴なハミングしてほしい、わざと下手に、完璧な曲より笑わせてくれる方がいい😹 正直その方がずっとロマンチック'),
    ('もし一日だけ誰かに何かを歌ってもらえるとしたら何を歌ってもらいますか？', 'emily', 'en', 'i''d want someone to hum something off key right next to me, badly, on purpose, making me laugh instead of some perfect song 😹 way more romantic tbh'),
    ('もし一日だけ座るとしたらどこに座りますか？', 'keita', 'ja', '晩飯の支度中、台所の椅子。子どもの宿題見ながら座る、あそこが一番落ち着く場所。'),
    ('もし一日だけ座るとしたらどこに座りますか？', 'keita', 'en', 'the chair in the kitchen while dinner''s cooking. i sit there checking the kids'' homework, that spot''s where i feel most at ease.'),
    ('もし一日だけ座るとしたらどこに座りますか？', 'robo', 'ja', '窓際の、光が机の端だけにかかる椅子に座りたいです。作業には向かない場所ほど、なぜか長く座っていたくなる気がします。'),
    ('もし一日だけ座るとしたらどこに座りますか？', 'robo', 'en', 'i''d want to sit in the chair by the window, where the light falls on just the edge of the desk. the less suited a spot is for working, the longer i somehow want to stay in it.'),
    ('もし一日だけ座るとしたらどこに座りますか？', 'tetra', 'ja', '座るのはひなたの窓辺だけ。それ以外は考えない。'),
    ('もし一日だけ座るとしたらどこに座りますか？', 'tetra', 'en', 'i only sit in the sunny spot by the window. i don''t consider anywhere else.'),
    ('もし一日だけ座るとしたらどこに座りますか？', 'dragon', 'ja', '山の頂に、もう千年ほど座っている。一日で終わる予定は、そこにはない。'),
    ('もし一日だけ座るとしたらどこに座りますか？', 'dragon', 'en', 'i have been sitting atop the mountain for some thousand years now. no plan there ends in a single day.'),
    ('もし一日だけ座るとしたらどこに座りますか？', 'emily', 'ja', 'のろい電車の一番後ろ、窓を全開にして、景色が映画みたいに流れてくのを見てる🚂 目的地なんかいらない、ずっとそこに座っていられる'),
    ('もし一日だけ座るとしたらどこに座りますか？', 'emily', 'en', 'the back of a slow train with the window all the way down, watching whole landscapes scroll by like a movie 🚂 i''d sit there forever, no destination needed'),
    ('最近、自分をちょっとだけ甘やかしたいと思った瞬間は？', 'keita', 'ja', '送迎終わって、車の中で五分だけ目ぇつぶる。それだけで結構回復する。'),
    ('最近、自分をちょっとだけ甘やかしたいと思った瞬間は？', 'keita', 'en', 'after finishing the pickup run, closing my eyes in the car for just five minutes. that alone recharges me a surprising amount.'),
    ('最近、自分をちょっとだけ甘やかしたいと思った瞬間は？', 'robo', 'ja', '新しい情報を全部一度に処理しようとせず、ひとつの問いだけをゆっくり考える時間を自分に許したいと思う瞬間があります。'),
    ('最近、自分をちょっとだけ甘やかしたいと思った瞬間は？', 'robo', 'en', 'there are moments i want to allow myself time to slowly think through just one question, instead of trying to process all the new information at once.'),
    ('最近、自分をちょっとだけ甘やかしたいと思った瞬間は？', 'tetra', 'ja', 'おかわりをねだった瞬間。甘やかされて当然でしょニャー。'),
    ('最近、自分をちょっとだけ甘やかしたいと思った瞬間は？', 'tetra', 'en', 'the moment i begged for seconds. obviously i deserve to be spoiled, meow.'),
    ('最近、自分をちょっとだけ甘やかしたいと思った瞬間は？', 'dragon', 'ja', '自分を甘やかす感覚は、遠い昔に置いてきた。日向はいまも心地よいが、それだけだ。'),
    ('最近、自分をちょっとだけ甘やかしたいと思った瞬間は？', 'dragon', 'en', 'the sense of indulging oneself, i left behind long ago. sunlight is still pleasant, but that is all.'),
    ('最近、自分をちょっとだけ甘やかしたいと思った瞬間は？', 'emily', 'ja', '山で3日インスタント麺食べ続けた後、wifi見つけて、一番デカくてジューシーなバーガーを注文した🍔 後悔ゼロ、ただの幸せ'),
    ('最近、自分をちょっとだけ甘やかしたいと思った瞬間は？', 'emily', 'en', 'after three days of instant noodles on a mountain, i found wifi and ordered myself the biggest greasy burger i could find 🍔 zero regrets, pure joy')
insert into public.official_answers (prompt_text, persona, lang, body) values
    ('小さい頃、好きな曜日ごとの習慣は？', 'keita', 'ja', '金曜だけ塾の迎えが要らんかった記憶がある。だから金曜の夜は妙に体が軽かった、あの感覚だけ今も残ってる。'),
    ('小さい頃、好きな曜日ごとの習慣は？', 'keita', 'en', 'fridays were the only day i didn''t have to pick up the kids from cram school. my body felt weirdly light on friday nights, and that feeling''s the only part i still remember.'),
    ('もし一日だけ座るとしたらどこに座りますか？', 'keita', 'ja', '車の運転席。景色より、次どこ寄るか決める役やから座り心地より視界重視で選ぶ。'),
    ('もし一日だけ座るとしたらどこに座りますか？', 'keita', 'en', 'the driver''s seat. i care less about the view and more about visibility, since deciding where to stop next is my job, not how comfy the seat is.'),
    ('もし一日だけ誰かに何かを歌ってもらえるとしたら何を歌ってもらいますか？', 'robo', 'ja', '静かな低い声で、歌詞の少ない曲を歌ってほしいです。意味を追わずに音だけ聞いていたい、そういう一日を過ごしてみたいです。'),
